 private Game.Input.IProxyAction NativeAction(string name){var manager=Game.Input.InputManager.instance;if(!object.ReferenceEquals(manager,_inputManager)){_inputManager=manager;_applyState=_restoreState=null;}var cached=name=="Upgrade Net Edge"?_applyState:_restoreState;if(cached!=null)return cached;var property=typeof(Game.Input.InputManager).GetProperty("toolActionCollection",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var collection=property?.GetValue(Game.Input.InputManager.instance) as Game.Input.UIInputActionCollection;if(collection==null){RuntimeDiagnostics.Event("Downgrade input collection unavailable");return null;}foreach(var alias in collection.m_InputActions)if(alias.aliasName==name){string label=name=="Upgrade Net Edge"?"TLK Apply Korean":"TLK Restore Default";var state=alias.GetState(GetType().Name,(source,action,mask,transform)=>new Game.Input.DisplayNameOverride(source,action,label,alias.displayPriority,alias.m_DisplayMask,transform));if(name=="Upgrade Net Edge")_applyState=state;else _restoreState=state;RuntimeDiagnostics.Count("tool.inputStateCreated");return state;}return null;}
