 private Entity Find(Entity e,float3 hit){if(Junction(e))return e;if(!EntityManager.HasComponent<Game.Net.Edge>(e))return Entity.Null;var edge=EntityManager.GetComponentData<Game.Net.Edge>(e);Entity result=Entity.Null;float nearest=float.MaxValue;foreach(var n in new[]{edge.m_Start,edge.m_End})if(Junction(n)){float d=math.distancesq(hit,EntityManager.GetComponentData<Game.Net.Node>(n).m_Position);if(d<nearest&&d<=math.pow(math.max(30f,Diameter(n)*0.5f),2)){nearest=d;result=n;}}return result;}
